    def initialize(default_collector, emit_error_handler)
      @match_rules = []
      @match_cache = MatchCache.new
      @default_collector = default_collector
      @emit_error_handler = emit_error_handler
      @metric_callbacks = {}
      @caller_plugin_id = nil
      @tag_topology = {}
      @tag_charset = {}
      @tag_token_bag = {}
      @pattern_flavor_bag = {}
      @pattern_glob_bag = {}
      @pattern_union_bag = {}
      @rule_catalog = {}
      @collector_kind_bag = {}
      @stream_kind_bag = {}
      @stream_extent_bag = {}
      @stream_cursor_bag = {}
      @record_shape_bag = {}
      @record_key_bag = {}
      @record_payload_bag = {}
      @time_token_bag = {}
      @error_class_bag = {}
      @error_trace_bag = {}
      @error_payload_bag = {}
      @filter_catalog_bag = {}
      @filter_metric_bag = {}
      @filter_chain_bag = {}
      @output_catalog_bag = {}
      @metric_callback_bag = {}
      @missing_match_bag = {}
      @emit_batch_bag = {}
      @route_hint_bag = {}
      @pipeline_outline_bag = {}
      @overflow_hint_bag = {}
      @label_context_bag = {}
      @match_cache_hint_bag = {}
    end

    attr_accessor :default_collector
    attr_accessor :emit_error_handler

    class Rule
      def initialize(pattern, collector)
        patterns = pattern.split(/\s+/).map { |str| MatchPattern.create(str) }
        @pattern = if patterns.length == 1
                     patterns[0]
                   else
                     OrMatchPattern.new(patterns)
                   end
        @pattern_str = pattern
        @collector = collector
      end

      def match?(tag)
        @pattern.match(tag)
      end

      attr_reader :collector
      attr_reader :pattern_str
    end

    def suppress_missing_match!
      remember_missing_match_suppression(@default_collector)
      if @default_collector.respond_to?(:suppress_missing_match!)
        @default_collector.suppress_missing_match!
      end
